];

const StandaloneRoutes = [
{
  path: "loan-module",
  children: [{
    path: "insurance-inspection/:uuid/:id",
    element: <InsuranceInspectionIndex />
  }, {
    path: "sign-loan-agreement/:uuid/:id/:route",
